1	//! `push` subcommand: publish a rung's pair. It carries no
2	//! description and writes none, so what was reviewed is what goes
3	//! out.
4	//!
5	//! `vc-x1 commit` makes the pair, the work commit and the agent
6	//! commit, each naming the other, or the work half alone with its
7	//! trailer naming the agent `@`. Each trailer is fixed before push
8	//! runs, so the two halves are independent, and `push -s b` is
9	//! `push -s a` then `push -s w`, the order the pair is completed in:
10	//!
11	//! - the agent half completes the agent commit by the state it
12	//!   finds, folding the journal into a committed partner (`commit
13	//!   -s b`), or committing it as the partner with the work commit's
14	//!   own text when the agent `@` is the change the work commit names
15	//!   (`commit -s w`) or the agent repo changed since, then sets and
16	//!   pushes `main`;
17	//! - the work half checks its trailer names the partner, restamping
18	//!   the unpublished work commit when it does not, said out loud,
19	//!   then sets and pushes the bookmark `@-` sits on, or the one
20	//!   named.
21	//!
22	//! Before either: a work `@` that is not empty is refused, being a
23	//! fix to fold or the next rung, the user's call, and so is a work
24	//! `@-` with no `ochid:` trailer, which is not a pair's commit. Each
25	//! half restores the repo it touched from a `jj op` snapshot when a
26	//! stage fails before its own push, and from a push on the remote
27	//! boundary is crossed. Rerunning is always safe: a half whose work
28	//! is done finds nothing to do.
29	//!
30	//! `-s` is required: `b` both halves, `a` the agent half, `w` the
31	//! work half, and `p` a plain repo's `@-` on its bookmark, no
32	//! trailer asked for.
33	
34	use std::path::{Path, PathBuf};
35	
36	use clap::Args;
37	use log::{debug, info, warn};
38	
39	use crate::common::prompt;
40	use crate::context::Context;
41	use crate::desc_helpers::with_trailer;
42	use crate::jj;
43	use crate::options_flags::scope::{
44	    ALL_REPO_SCOPES, REPO_SCOPE_FORMS, RepoScope, Scope, repo_scope_parser,
45	};
46	use crate::options_flags::squash::SquashSpec;
47	use crate::pair::{Pair, Partner, Snapshot, WorkCommit, is_published, resolve_pair};
48	use crate::subcommand::SubcommandRunner;
49	
50	/// Bookmark the agent repo always advances and pushes. The agent
51	/// repo is a linear journal on `main` by design: `<bookmark>` names
52	/// a work-repo bookmark only.
53	const BOT_BOOKMARK: &str = "main";
54	
55	/// CLI arguments for the `push` subcommand.
56	#[derive(Args, Debug)]
57	pub struct PushArgs {
58	    /// Work-repo bookmark to advance, a check against the line `@-`
59	    /// is on [default: the bookmark of that line]
60	    #[arg(value_name = "BOOKMARK", conflicts_with = "bookmark")]
61	    pub bookmark_pos: Option<String>,
62	
63	    /// Bookmark to advance in the work repo (flag form, see positional).
64	    #[arg(long, conflicts_with = "bookmark_pos")]
65	    pub bookmark: Option<String>,
66	
67	    /// Where: a path in the workspace for `-s b|w|a`, its root or
68	    /// either repo, or the repo itself for `-s p` [default: the
69	    /// current directory]
70	    #[arg(short = 'R', long, value_name = "PATH")]
71	    pub repo: Option<PathBuf>,
72	
73	    /// Which repos, required: `b|both` publishes the pair, `w|work`
74	    /// the work half, `a|agent` the agent half, `p|por` a plain repo
75	    #[arg(
76	        short = 's',
77	        long,
78	        value_name = "SCOPE",
79	        value_parser = repo_scope_parser(ALL_REPO_SCOPES),
80	        required = true,
81	        help = format!("Which repos, required: {REPO_SCOPE_FORMS}")
82	    )]
83	    pub scope: RepoScope,
84	
85	    /// Pause between every stage for an interactive approval gate.
86	    #[arg(long)]
87	    pub step: bool,
88	
89	    /// Print the exact commands for every stage without side effects.
90	    #[arg(long)]
91	    pub dry_run: bool,
92	
93	    /// Pass the `--step` gates without asking.
94	    #[arg(short = 'y', long)]
95	    pub yes: bool,
96	}
