183	/// Refuse a named bookmark that is no bookmark but a revision, such
184	/// as `@-`: push publishes `@-` on the bookmark it sits on, found when
185	/// none is named, so a revision is never what the name means.
186	fn refuse_a_revision(repo: &Path, params: &PushParams) -> Result<(), Box<dyn std::error::Error>> {
187	    let Some(name) = &params.bookmark else {
188	        return Ok(());
189	    };
190	    if jj::local_bookmark_exists(repo, name)? || !jj::rev_exists(repo, name)? {
191	        return Ok(());
192	    }
193	    Err(format!(
194	        "push: '{name}' is a revision, not a bookmark. Push publishes @- on the bookmark it \
195	         sits on, found when none is named, so leave it out or name the bookmark"
196	    )
197	    .into())
198	}
199	
200	/// A named bookmark off the work `@-`'s line, on a commit already
201	/// made: publish it where it is, a name and no pair, and say so. True
202	/// when it was this case. The working copy, which holds changes not
203	/// yet committed, and the root, which has nothing to publish, are
204	/// refused, `vc-x1 commit` being what turns the working copy into a
205	/// commit. A bookmark on the line goes the pair's way.
206	fn publish_name(
207	    ctx: &mut Context,
208	    repo: &Path,
209	    params: &PushParams,
210	) -> Result<bool, Box<dyn std::error::Error>> {
211	    let Some(name) = &params.bookmark else {
212	        return Ok(false);
213	    };
214	    if !jj::local_bookmark_exists(repo, name)?
215	        || jj::local_bookmarks_at(repo, "heads(::@- & bookmarks())")?.contains(name)
216	    {
217	        return Ok(false);
218	    }
219	    if jj::local_bookmarks_at(repo, "@")?.contains(name) {
220	        return Err(format!(
221	            "push: '{name}' is on the working copy, which is not committed: `vc-x1 commit` \
222	             commits it and pushes it"
223	        )
224	        .into());
225	    }
226	    if jj::local_bookmarks_at(repo, "root()")?.contains(name) {
227	        return Err(
228	            format!("push: '{name}' is on the root commit, which has nothing to publish").into(),
229	        );
230	    }
231	    let at = jj::cid_of(repo, name)?;
232	    if params.dry_run {
233	        info!("push: [dry-run] publish '{name}' where it is, {at}, a commit already made");
234	        return Ok(true);
235	    }
236	    info!("push: publish '{name}' where it is, {at}, a commit already made");
237	    ctx.session(repo)?.git_push_bookmark(name)?;
238	    Ok(true)
239	}
