241	/// `push` on a dual workspace, parameterized on the pair and the
242	/// sides to publish. CLI dispatch resolves these from `-s` and `-R`,
243	/// and integration tests pass a fixture's pair.
244	///
245	/// The checks every half needs run first, then the agent half, then
246	/// the work half, each restoring its own repo on a local failure.
247	pub(crate) fn push_in(
248	    ctx: &mut Context,
249	    pair: &Pair,
250	    sides: &Scope,
251	    params: &PushParams,
252	) -> Result<(), Box<dyn std::error::Error>> {
253	    if params.dry_run {
254	        info!("push: DRY-RUN: no side effects (no commits, no pushes)");
255	    }
256	    // The dual-mode preflight: both repos' recorded topology agrees.
257	    crate::common::require_bot_dir(&pair.work)?;
258	    // New work in the work `@` is the next rung's, and push publishes
259	    // `@-`, so it is left as it is.
260	    let held = sides.has_work() && !jj::is_empty(&pair.work, "@")?;
261	    if held {
262	        info!("push: the work @ holds new work, left as it is, and @- is what goes out");
263	    }
264	    let Some(work) = crate::pair::work_commit(pair)? else {
265	        return Err(
266	            "push: the work repo's @- carries no `ochid:` trailer, so it is not a \
267	                    pair's commit. Make the pair with `vc-x1 commit -s b` or `-s w` first"
268	                .into(),
269	        );
270	    };
271	    // The bookmark first, so a run whose work half cannot publish
272	    // stops before the agent half publishes anything.
273	    let bookmark = if sides.has_work() {
274	        Some(resolve_bookmark(&pair.work, params)?)
275	    } else {
276	        None
277	    };
278	
279	    let partner = if sides.has_bot() {
280	        Some(agent_half(ctx, pair, &work, params)?)
281	    } else {
282	        None
283	    };
284	    if let Some(bookmark) = &bookmark {
285	        if sides.has_bot() {
286	            step_gate(params, "the agent half", "the work half")?;
287	        }
288	        work_half(ctx, pair, &work, bookmark, params)?;
289	    }
290	
291	    if params.dry_run {
292	        info!("push: DRY-RUN complete: no changes written");
293	        return Ok(());
294	    }
295	    // Honest completion, warning-only: the remote boundary is crossed
296	    // by now, so the user investigates rather than a rollback.
297	    let run = Run {
298	        work: bookmark.map(|b| (b, work.chid.clone())),
299	        partner,
300	        held,
301	    };
302	    match verify_completion(pair, &run) {
303	        Ok(()) => info!("push: completed all stages (verified)"),
304	        Err(e) => {
305	            warn!("push: completed stages but post-completion verification failed:");
306	            warn!("  {e}");
307	            warn!("  investigate the discrepancy before the next push");
308	        }
309	    }
310	    Ok(())
311	}
312	
313	/// The work bookmark: the one named, which must be among the nearest
314	/// bookmarks below the work `@-`, else the line's own.
315	fn resolve_bookmark(
316	    root: &Path,
317	    params: &PushParams,
318	) -> Result<String, Box<dyn std::error::Error>> {
319	    match &params.bookmark {
320	        Some(b) => {
321	            if !jj::local_bookmark_exists(root, b)? {
322	                return Err(format!("push: bookmark '{b}' does not exist in the work repo").into());
323	            }
324	            let nearest = jj::local_bookmarks_at(root, "heads(::@- & bookmarks())")?;
325	            if !nearest.contains(b) {
326	                return Err(format!(
327	                    "push: bookmark '{b}' is not the nearest bookmark below the work @-, the \
328	                     line's own ({}). Name one of them, or none to use the line's",
329	                    nearest.join(", ")
330	                )
331	                .into());
332	            }
333	            Ok(b.clone())
334	        }
335	        None => crate::squash_push::current_bookmark(root, "@-"),
336	    }
337	}
338	
339	/// The agent half: complete the partner by the state found, then set
340	/// and push `main`. Returns the partner's change id, where `main`
341	/// ends.
342	fn agent_half(
343	    ctx: &mut Context,
344	    pair: &Pair,
345	    work: &WorkCommit,
346	    params: &PushParams,
347	) -> Result<String, Box<dyn std::error::Error>> {
348	    // The intent lines carry the dry-run tag too, or they read as done.
349	    let dry = if params.dry_run { "[dry-run] " } else { "" };
350	    let (partner, commit_journal) = match crate::pair::partner(pair, work)? {
351	        Partner::Committed(partner) => {
352	            info!(
353	                "push agent: {dry}fold the journal into the partner at @- {partner}, which names the \
354	                 work commit, and publish {BOT_BOOKMARK}"
355	            );
356	            (partner, false)
357	        }
358	        Partner::Pending(agent_at) => {
359	            info!(
360	                "push agent: {dry}commit the agent @ {agent_at} as the partner, the change the work \
361	                 commit names, and publish {BOT_BOOKMARK}"
362	            );
363	            (agent_at, true)
364	        }
365	        Partner::Changed { stamped, agent_at } => {
366	            // The work half will restamp, which a published work
367	            // commit cannot take, so stop before anything moves.
368	            if is_published(&pair.work, "@-")? {
369	                return Err(
370	                    "push: the work @- is published and names an agent change that is \
371	                            no longer the partner, so it cannot be restamped. Put the agent repo \
372	                            back at the change it names, or make a new pair"
373	                        .into(),
374	                );
375	            }
376	            warn!(
377	                "push agent: {dry}the work commit names {stamped}, which is neither the agent @ nor \
378	                 the partner at @-, so the agent repo changed since the commit. Commit the agent \
379	                 @ {agent_at} as the partner and publish {BOT_BOOKMARK}, and the work half \
380	                 restamps the work commit to name it"
381	            );
382	            (agent_at, true)
383	        }
384	    };
385	    let agent_arg = pair.agent.to_string_lossy();
386	    if params.dry_run {
387	        if commit_journal {
388	            info!("push agent: [dry-run] would run jj commit -R {agent_arg} -m <work text+ochid>");
389	        }
390	        info!("push agent: [dry-run] would squash @ -> @- and push {BOT_BOOKMARK} -R {agent_arg}");
391	        return Ok(partner);
392	    }
393	    if commit_journal {
394	        let text = without_trailers(&jj::desc_of(&pair.work, "@-")?);
395	        let desc = with_trailer(&text, &format!("/{}", work.chid));
396	        let snapshot = Snapshot::take(&pair.agent)?;
397	        info!("push agent: commit -R {agent_arg}");
398	        if let Err(e) = ctx.session(&pair.agent)?.commit(&desc) {
399	            snapshot.restore("push agent", e.as_ref());
400	            return Err(e);
401	        }
402	        step_gate(params, "the agent commit", "the agent publish")?;
403	    }
404	    info!("push agent: squash @ -> @- + push {BOT_BOOKMARK} -R {agent_arg}");
405	    let sp = crate::squash_push::SquashPushParams {
406	        repo: pair.agent.clone(),
407	        squash: SquashSpec {
408	            source: "@".to_string(),
409	            target: "@-".to_string(),
410	        },
411	        bookmark: BOT_BOOKMARK.to_string(),
412	        // Mid-push the mismatch is the normal state, since this stage
413	        // is what publishes main: don't report a lost publish.
414	        at_rest: false,
415	        yes: true,
416	        dry_run: false,
417	    };
418	    crate::squash_push::squash_push(ctx, &sp)?;
419	    Ok(partner)
420	}
421	
422	/// The work half: restamp the unpublished work commit when its
423	/// trailer does not name the partner, then set and push the bookmark.
424	fn work_half(
425	    ctx: &mut Context,
426	    pair: &Pair,
427	    work: &WorkCommit,
428	    bookmark: &str,
429	    params: &PushParams,
430	) -> Result<(), Box<dyn std::error::Error>> {
431	    let target = match crate::pair::partner(pair, work)? {
432	        Partner::Committed(partner) => partner,
433	        Partner::Pending(agent_at) | Partner::Changed { agent_at, .. } => agent_at,
434	    };
435	    let restamp = work.stamped != target;
436	    let dry = if params.dry_run { "[dry-run] " } else { "" };
437	    if restamp {
438	        if is_published(&pair.work, "@-")? {
439	            return Err(format!(
440	                "push: the work @- is published and names {}, not the partner {target}, so it \
441	                 cannot be restamped",
442	                work.stamped
443	            )
444	            .into());
445	        }
446	        warn!(
447	            "push work: {dry}publish {} on {bookmark}, restamping its trailer to name the partner {target}",
448	            work.chid
449	        );
450	    } else {
451	        info!("push work: {dry}publish {} on {bookmark}", work.chid);
452	    }
453	    let work_arg = pair.work.to_string_lossy();
454	    if params.dry_run {
455	        info!("push work: [dry-run] would run jj bookmark set {bookmark} -r @- -R {work_arg}");
456	        info!("push work: [dry-run] would run jj git push --bookmark {bookmark} -R {work_arg}");
457	        return Ok(());
458	    }
459	    let snapshot = Snapshot::take(&pair.work)?;
460	    let local = (|| -> Result<(), Box<dyn std::error::Error>> {
461	        if restamp {
462	            let text = without_trailers(&jj::desc_of(&pair.work, "@-")?);
463	            let prefix = crate::desc_helpers::ochid_prefix_for(&pair.agent)?;
464	            info!("push work: restamp @- to name {target}");
465	            ctx.session(&pair.work)?
466	                .describe("@-", &with_trailer(&text, &format!("{prefix}{target}")))?;
467	        }
468	        info!("push work: bookmark set {bookmark} -r @- -R {work_arg}");
469	        ctx.session(&pair.work)?.bookmark_set(bookmark, "@-")?;
470	        Ok(())
471	    })();
472	    if let Err(e) = local {
473	        snapshot.restore("push work", e.as_ref());
474	        return Err(e);
475	    }
476	    step_gate(params, "the work bookmark", "the work push")?;
477	    crate::common::verify_tracking(&pair.work, bookmark)?;
478	    info!("push work: git push --bookmark {bookmark} -R {work_arg}");
479	    ctx.session(&pair.work)?.git_push_bookmark(bookmark)?;
480	    Ok(())
481	}
482	
483	/// A description without its `ochid:` lines, trimmed, the text a
484	/// partner commit shares.
485	fn without_trailers(desc: &str) -> String {
486	    desc.lines()
487	        .filter(|l| !l.starts_with("ochid:"))
488	        .collect::<Vec<_>>()
489	        .join("\n")
490	        .trim_end()
491	        .to_string()
492	}
493	
494	/// `--step`: pause between stages so the user can inspect the repos
495	/// before the next one runs. `--yes` passes the gates, and a non-tty
496	/// without it is an error rather than a hang.
497	fn step_gate(
498	    params: &PushParams,
499	    done: &str,
500	    next: &str,
501	) -> Result<(), Box<dyn std::error::Error>> {
502	    if !params.step {
503	        return Ok(());
504	    }
505	    if params.yes {
506	        debug!("push step: --yes skips step gate between {done} and {next}");
507	        return Ok(());
508	    }
509	    if !is_stdin_tty() {
510	        return Err("push: --step requires a tty (stdin is not interactive); \
511	                    add --yes to bypass step gates in non-interactive contexts"
512	            .into());
513	    }
514	    let answer = prompt(&format!(
515	        "push step: {done} done. Continue to {next}? [y/N] "
516	    ))?;
517	    let normalized = answer.trim().to_ascii_lowercase();
518	    if normalized != "y" && normalized != "yes" {
519	        return Err(format!("push: step gate declined after {done} (got {answer:?})").into());
520	    }
521	    Ok(())
522	}
523	
524	/// Verify the world matches what the halves claim: the work
525	/// bookmark at the work commit and the work `@` empty unless it held
526	/// new work when the run began, and the agent `main` at the partner. The agent `@` may hold new session writes
527	/// that landed after the squash, so it is not checked.
528	fn verify_completion(pair: &Pair, run: &Run) -> Result<(), Box<dyn std::error::Error>> {
529	    if let Some((bookmark, work_chid)) = &run.work {
530	        let actual = jj::chid_of(&pair.work, bookmark)?;
531	        if actual != *work_chid {
532	            return Err(format!(
533	                "completion sanity: work bookmark '{bookmark}' is at chid '{actual}' but this \
534	                 run published '{work_chid}'."
535	            )
536	            .into());
537	        }
538	        if !run.held && !jj::is_empty(&pair.work, "@")? {
539	            let wc_diff = jj::diff_stat(&pair.work)?;
540	            return Err(format!(
541	                "completion sanity: work working copy has uncommitted changes. Diff stat:\n{wc_diff}"
542	            )
543	            .into());
544	        }
545	    }
546	    if let Some(partner) = &run.partner {
547	        let actual = jj::chid_of(&pair.agent, BOT_BOOKMARK)?;
548	        if actual != *partner {
549	            return Err(format!(
550	                "completion sanity: agent bookmark '{BOT_BOOKMARK}' is at chid '{actual}' but \
551	                 this run published '{partner}'."
552	            )
553	            .into());
554	        }
555	    }
556	    Ok(())
557	}
558	
559	/// `push -s p`: a plain repo's `@-` goes out on its bookmark, no
560	/// trailer asked for, the work half's checks otherwise.
561	fn push_por(
562	    ctx: &mut Context,
563	    repo: &Path,
564	    params: &PushParams,
565	) -> Result<(), Box<dyn std::error::Error>> {
566	    if !jj::is_empty(repo, "@")? {
567	        info!("push -s p: @ holds new work, left as it is, and @- is what goes out");
568	    }
569	    if jj::desc_of(repo, "@-")?.trim().is_empty() {
570	        return Err("push -s p: @- has no description, so it is not a commit to publish".into());
571	    }
572	    let bookmark = match &params.bookmark {
573	        Some(b) => b.clone(),
574	        None => crate::squash_push::current_bookmark(repo, "@-")?,
575	    };
576	    let arg = repo.to_string_lossy();
577	    if params.dry_run {
578	        info!(
579	            "push: [dry-run] would run jj bookmark set {bookmark} -r @- -R {arg}, then git push --bookmark {bookmark}"
580	        );
581	        return Ok(());
582	    }
583	    info!("push bookmark-set: bookmark set {bookmark} -r @- -R {arg}");
584	    ctx.session(repo)?.bookmark_set(&bookmark, "@-")?;
585	    crate::common::verify_tracking(repo, &bookmark)?;
586	    info!("push push-work: git push --bookmark {bookmark} -R {arg}");
587	    ctx.session(repo)?.git_push_bookmark(&bookmark)?;
588	    info!("push: completed");
589	    Ok(())
590	}
591	
592	#[cfg(test)]
593	mod tests;
594	
595	#[cfg(test)]
596	mod integration_tests;

