336	        .map(|c| c.id().hex())
337	        .collect();
338	    ids.reverse();
339	    Ok(ids)
340	}
341	
342	/// The full commit ids of `rev`'s parents, in parent order, `rev`
343	/// being exactly one commit.
344	pub fn parent_cids_of(repo: &Path, rev: &str) -> Result<Vec<String>> {
345	    match commits_of(repo, rev)?.as_slice() {
346	        [commit] => Ok(commit.parent_ids().iter().map(|id| id.hex()).collect()),
347	        other => Err(format!(
348	            "expected exactly one commit for {rev:?}, got {}",
349	            other.len()
350	        )
351	        .into()),
352	    }
353	}
354	
355	/// True when any commit of `rev` is in jj's `immutable()`, as `jj`
356	/// evaluates it with the user's and the repo's config.
357	pub fn is_immutable(repo: &Path, rev: &str) -> Result<bool> {
358	    session::RepoSession::open(repo)?.is_immutable(rev)
359	}
360	
361	/// The 12-character commit id of `rev`.
362	pub fn cid_short_of(repo: &Path, rev: &str) -> Result<String> {
363	    Ok(cids_short_of(repo, rev)?.concat())
364	}
365	
366	/// 12-character commit ids of every commit `revset` resolves to:
367	/// the multi-result sibling of `cid_short_of` (e.g. the heads of a
368	/// conflicted bookmark).
369	pub fn cids_short_of(repo: &Path, revset: &str) -> Result<Vec<String>> {
370	    Ok(commits_of(repo, revset)?
371	        .iter()
372	        .map(|c| {
373	            let hex = c.id().hex();
374	            hex[..hex.len().min(12)].to_string()
375	        })
376	        .collect())
377	}
378	
379	/// The full description (title + body) of `rev`, surrounding
380	/// whitespace trimmed (the shape the spawned `-T description` form
381	/// returned, which every caller still expects).
382	pub fn desc_of(repo: &Path, rev: &str) -> Result<String> {
383	    let all: String = commits_of(repo, rev)?
384	        .iter()
385	        .map(|c| c.description())
386	        .collect();
387	    Ok(all.trim().to_string())
388	}
389	
390	/// True when `rev` is empty (no file changes relative to its
391	/// parent). Strict: exactly one commit must resolve.
392	pub fn is_empty(repo: &Path, rev: &str) -> Result<bool> {
393	    let (workspace, repo_at_head) = repo_for_read(repo, rev)?;
394	    let ids = common::resolve_revset(&workspace, &repo_at_head, rev)?;
395	    match ids.as_slice() {
396	        [id] => {
397	            let commit = repo_at_head.store().get_commit(id)?;
398	            Ok(commit.is_empty(repo_at_head.as_ref()).block_on()?)
399	        }
400	        other => Err(format!(
401	            "jj::is_empty: expected exactly one commit for {rev:?}, got {}",
402	            other.len()
403	        )
404	        .into()),
405	    }
406	}
407	
408	/// True when the local bookmark `name` exists (what
409	/// `jj bookmark list <name>` printing anything used to mean).
410	pub fn local_bookmark_exists(repo: &Path, name: &str) -> Result<bool> {
411	    let (_workspace, repo_at_head) = common::load_repo(repo)?;
412	    let name = RefName::new(name);
413	    Ok(repo_at_head.view().get_local_bookmark(name).is_present())
414	}
415	
416	/// The local bookmarks pointing at any commit `revset` resolves to,
417	/// sorted and deduplicated.
418	///
419	/// Used to answer "which branch am I on", which jj has no single
420	/// word for: the caller asks about the nearest bookmarked ancestor
421	/// and reads the names back from here.
422	pub fn local_bookmarks_at(repo: &Path, revset: &str) -> Result<Vec<String>> {
423	    let (workspace, repo_at_head) = repo_for_read(repo, revset)?;
424	    let ids = common::resolve_revset(&workspace, &repo_at_head, revset)?;
425	    let mut names: Vec<String> = repo_at_head
426	        .view()
427	        .local_bookmarks()
428	        .filter(|(_, target)| target.adds().flatten().any(|id| ids.contains(id)))
429	        .map(|(name, _)| name.as_str().to_string())
430	        .collect();
431	    names.sort();
432	    names.dedup();
433	    Ok(names)
434	}
435	
436	/// The remote bookmarks pointing at any commit `revset` resolves to,
437	/// as `(name, remote)` pairs, sorted, the local git repo's pseudo-remote
438	/// left out as `remote_bookmarks()` leaves it.
439	pub fn remote_bookmarks_at(repo: &Path, revset: &str) -> Result<Vec<(String, String)>> {

